import{_ as t,o as s,c as a,ag as o}from"./chunks/framework.BIas3y6W.js";const p=JSON.parse('{"title":"How the Web Works","description":"","frontmatter":{"source":"resources/web-basics.md"},"headers":[],"relativePath":"resources/web-basics.md","filePath":"resources/web-basics.md"}'),r={name:"resources/web-basics.md"};function n(i,e,d,h,l,c){return s(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="how-the-web-works" tabindex="-1">How the Web Works <a class="header-anchor" href="#how-the-web-works" aria-label="Permalink to &quot;How the Web Works&quot;">​</a></h1><blockquote><p>A plain-English guide to the web for people who can program a little but haven&#39;t built for the web. Read it before week 1 if you like, and again before week 9, when it matters most. The one idea to take away: <strong>anything that reaches the browser is public. Secrets and rules belong on the server.</strong></p></blockquote><p><strong>Know Python but not JavaScript?</strong> Start with <a href="./../setup/python-to-javascript.html">From Python to JavaScript</a> in week 0. It covers the language; this page covers the web around it.</p><p><strong>On this page:</strong> <a href="#browsers-and-servers">Browsers and servers</a> · <a href="#urls">URLs</a> · <a href="#html-css-and-javascript">HTML, CSS and JavaScript</a> · <a href="#requests-and-responses-http">Requests and responses (HTTP)</a> · <a href="#json">JSON</a> · <a href="#apis">APIs</a> · <a href="#front-end-and-back-end">Front end and back end</a> · <a href="#static-and-dynamic-sites">Static and dynamic sites</a> · <a href="#cdns-code-from-someone-elses-server">CDNs</a> · <a href="#databases">Databases</a> · <a href="#the-trust-boundary">The trust boundary</a> · <a href="#a-short-devtools-tour">A short DevTools tour</a> · <a href="#try-it-10-minutes">Try it</a></p><hr><h2 id="browsers-and-servers" tabindex="-1">Browsers and servers <a class="header-anchor" href="#browsers-and-servers" aria-label="Permalink to &quot;Browsers and servers&quot;">​</a></h2><p>The web is a conversation between two kinds of program.</p><ul><li>A <strong>browser</strong> (Chrome, Edge, Firefox, Safari) runs on the visitor&#39;s device. It asks for pages and shows them.</li><li>A <strong>server</strong> runs on a computer somewhere else. It waits for requests and sends back answers.</li></ul><p>When you type an address and press Enter, your browser sends a <strong>request</strong> across the internet. A server sends back a <strong>response</strong>, usually a file. The browser reads that file, notices it needs more files (a stylesheet, a script, some images), and asks for each one. Then it assembles the page on your screen.</p><p><em>It works like a restaurant. You (the browser) order from the menu. The kitchen (the server) cooks and sends out dishes. You never see the kitchen, but you can inspect everything that reaches your table.</em></p><p>That last sentence is the most important security idea in the course. We come back to it in <a href="#the-trust-boundary">the trust boundary</a>.</p><h2 id="urls" tabindex="-1">URLs <a class="header-anchor" href="#urls" aria-label="Permalink to &quot;URLs&quot;">​</a></h2><p>A <strong>URL</strong> is a web address. Every part of it means something:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://ada.github.io/game/index.html?level=2#scores</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Part</th><th>In the example</th><th>What it means</th></tr></thead><tbody><tr><td>Protocol</td><td><code>https://</code></td><td>How to talk. The <code>s</code> means the conversation is encrypted.</td></tr><tr><td>Host (domain)</td><td><code>ada.github.io</code></td><td>Which server to ask.</td></tr><tr><td>Path</td><td><code>/game/index.html</code></td><td>Which file or <a href="./glossary.html#endpoint">endpoint</a> on that server. If you leave off the file name, most servers look for <code>index.html</code>.</td></tr><tr><td>Query</td><td><code>?level=2</code></td><td>Extra information for the page or server, as <code>name=value</code> pairs.</td></tr><tr><td>Fragment</td><td><code>#scores</code></td><td>A spot on the page to scroll to. It is never sent to the server.</td></tr></tbody></table><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Never put personal data, passwords or keys in a URL. URLs are saved in browser history, in server logs and in anything you share.</p></div><p>Paths are <strong>case-sensitive</strong> on most servers, GitHub Pages included: <code>Game/Index.html</code> and <code>game/index.html</code> are different files. That one detail causes many &quot;404 Not Found&quot; errors (<a href="./troubleshooting.html#github-pages-shows-404">troubleshooting</a>).</p><h2 id="html-css-and-javascript" tabindex="-1">HTML, CSS and JavaScript <a class="header-anchor" href="#html-css-and-javascript" aria-label="Permalink to &quot;HTML, CSS and JavaScript&quot;">​</a></h2><p>Every web page is built from three languages, each with one job:</p><table tabindex="0"><thead><tr><th>Language</th><th>Job</th><th>House analogy</th><th>Tiny example</th></tr></thead><tbody><tr><td><strong>HTML</strong></td><td>Structure and content: headings, paragraphs, buttons, images</td><td>Walls and rooms</td><td><code>&lt;button id=&quot;add&quot;&gt;Add&lt;/button&gt;</code></td></tr><tr><td><strong>CSS</strong></td><td>Appearance: colors, fonts, spacing, layout</td><td>Paint and furniture</td><td><code>button { background: teal; }</code></td></tr><tr><td><strong>JavaScript</strong></td><td>Behavior: what happens when you click, type or load</td><td>Wiring and electricity</td><td><code>button.addEventListener(&#39;click&#39;, addItem)</code></td></tr></tbody></table><p>In your projects these usually live in three files: <code>index.html</code>, <code>style.css</code> and <code>app.js</code>. The HTML file links to the other two.</p><p>When the browser reads your HTML, it builds a live model of the page in memory called the <strong>DOM</strong> (<a href="./glossary.html#dom">glossary</a>). JavaScript changes what you see by changing the DOM, for example adding a new list item. Reload the page and the browser rebuilds the DOM from the HTML file, so anything JavaScript added is gone unless you saved it somewhere, such as <a href="./glossary.html#localstorage">localStorage</a>.</p><h2 id="requests-and-responses-http" tabindex="-1">Requests and responses (HTTP) <a class="header-anchor" href="#requests-and-responses-http" aria-label="Permalink to &quot;Requests and responses (HTTP)&quot;">​</a></h2><p><strong>HTTP</strong> is the set of rules for the browser–server conversation. Each exchange is one request and one response. Here is what your week 9 app sends when someone asks it a question. You can see exactly this in DevTools → Network.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>REQUEST  (browser → server)</span></span>
<span class="line"><span>POST /api/ask</span></span>
<span class="line"><span>Content-Type: application/json</span></span>
<span class="line"><span></span></span>
<span class="line"><span>{&quot;question&quot;: &quot;Suggest a name for my cat&quot;}</span></span>
<span class="line"><span></span></span>
<span class="line"><span></span></span>
<span class="line"><span>RESPONSE  (server → browser)</span></span>
<span class="line"><span>200 OK</span></span>
<span class="line"><span>Content-Type: application/json</span></span>
<span class="line"><span></span></span>
<span class="line"><span>{&quot;reply&quot;: &quot;How about Captain Whiskers?&quot;}</span></span></code></pre></div><p>A request has:</p><ul><li>a <strong>method</strong>: <code>GET</code> to fetch something, <code>POST</code> to send something;</li><li>a <strong>URL</strong>: where it goes;</li><li><strong>headers</strong>: labels such as the content type, or an <code>Authorization</code> header that carries a key;</li><li>sometimes a <strong>body</strong>: the data being sent.</li></ul><p>A response has a <strong>status code</strong>, headers and a body.</p><h3 id="status-codes-you-will-meet" tabindex="-1">Status codes you will meet <a class="header-anchor" href="#status-codes-you-will-meet" aria-label="Permalink to &quot;Status codes you will meet&quot;">​</a></h3><p>The first digit tells you whose problem it is: <strong>2</strong> means it worked, <strong>4</strong> means the request was wrong, <strong>5</strong> means the server broke.</p><table tabindex="0"><thead><tr><th>Code</th><th>Name</th><th>What it usually means in this course</th></tr></thead><tbody><tr><td><code>200</code></td><td>OK</td><td>It worked.</td></tr><tr><td><code>304</code></td><td>Not Modified</td><td>The browser used its cached copy. Fine, unless you expected a change (<a href="./glossary.html#hard-reload">hard reload</a>).</td></tr><tr><td><code>400</code></td><td>Bad Request</td><td>What you sent was malformed, such as broken JSON or a missing field.</td></tr><tr><td><code>401</code></td><td>Unauthorized</td><td>The key or login is missing or wrong.</td></tr><tr><td><code>403</code></td><td>Forbidden</td><td>The server knows who you are and says no.</td></tr><tr><td><code>404</code></td><td>Not Found</td><td>Wrong path, wrong file name (check capital letters), or wrong model name.</td></tr><tr><td><code>405</code></td><td>Method Not Allowed</td><td>Wrong method, such as opening a POST-only route like <code>/api/ask</code> in the address bar (which sends a GET).</td></tr><tr><td><code>415</code></td><td>Unsupported Media Type</td><td>The request didn&#39;t say it was JSON: it&#39;s missing the <code>Content-Type: application/json</code> header.</td></tr><tr><td><code>429</code></td><td>Too Many Requests</td><td>You hit a <a href="./glossary.html#rate-limit">rate limit</a>. Slow down or wait.</td></tr><tr><td><code>500</code></td><td>Internal Server Error</td><td>Your server code crashed, or (in the course starters) your server isn&#39;t set up right, for example a missing or rejected key. Read the server&#39;s log, not the browser&#39;s.</td></tr><tr><td><code>502</code></td><td>Bad Gateway</td><td>Something behind the server failed or isn&#39;t running.</td></tr><tr><td><code>504</code></td><td>Gateway Timeout</td><td>Something behind the server took too long to answer.</td></tr></tbody></table><p>There can be two status codes in one exchange: the one the AI provider sends your server, and the one your server sends the browser. The course starters translate the first into the second, so a wrong key, which the provider reports as <code>401</code>, reaches your page as a <code>500</code> with a message saying the key was rejected. What to do about each one: <a href="./troubleshooting.html#my-api-call-returns-an-error">Troubleshooting: My API call returns an error</a>.</p><h2 id="json" tabindex="-1">JSON <a class="header-anchor" href="#json" aria-label="Permalink to &quot;JSON&quot;">​</a></h2><p><strong>JSON</strong> is a plain-text format for structured data. Almost every API speaks it.</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;title&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Water the plants&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;done&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;tags&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;home&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;weekly&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;dueInDays&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Curly braces <code>{ }</code> hold named values, square brackets <code>[ ]</code> hold lists, text goes in &quot;double quotes&quot;, and <code>true</code>, <code>false</code> and numbers don&#39;t. JSON is strict: single quotes or a comma after the last item make it invalid, and you&#39;ll see an error such as <code>Unexpected token</code>. Your apps also use JSON to save lists in localStorage, because localStorage can only store text.</p><h2 id="apis" tabindex="-1">APIs <a class="header-anchor" href="#apis" aria-label="Permalink to &quot;APIs&quot;">​</a></h2><p>An <strong>API</strong> is a menu of requests one program can make to another. <em>Like ordering through a waiter: you choose from a fixed menu, you get a dish back, and you never enter the kitchen.</em></p><p>In weeks 9–10 your app uses an LLM provider&#39;s API:</p><ol><li>The user types a question on your page.</li><li>Your page sends it to <strong>your own server</strong> (<code>/api/ask</code>).</li><li>Your server adds the secret <a href="./glossary.html#api-key">API key</a> and sends the question to the provider&#39;s API.</li><li>The provider sends back an answer as JSON. Your server passes the useful part back to the page.</li></ol><p>Why the extra hop through your server? Because the key must never reach the browser. If the page called the provider directly, the key would be sitting in public code, and anyone could copy it and spend your quota.</p><p>Many providers accept the same request format, called an <a href="./glossary.html#openai-compatible-api">OpenAI-compatible API</a>. That is why the course starter can switch providers by changing settings instead of code. Current providers: <a href="./../TOOLS.html">Tool Handout</a>.</p><h2 id="front-end-and-back-end" tabindex="-1">Front end and back end <a class="header-anchor" href="#front-end-and-back-end" aria-label="Permalink to &quot;Front end and back end&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Front end</th><th>Back end</th></tr></thead><tbody><tr><td>Runs on</td><td>The visitor&#39;s browser</td><td>A server (for us, a Vercel function)</td></tr><tr><td>Who can read the code</td><td><strong>Anyone</strong> (DevTools → Sources)</td><td>Only you and your host</td></tr><tr><td>Made of</td><td>HTML, CSS, JavaScript</td><td>JavaScript running on <a href="./glossary.html#nodejs">Node.js</a>, plus databases</td></tr><tr><td>In the course starters</td><td><code>public/</code> folder</td><td><code>api/</code> folder</td></tr><tr><td>Safe place for secrets?</td><td><strong>Never</strong></td><td>Yes, in <a href="./glossary.html#environment-variable">environment variables</a></td></tr><tr><td>Can enforce rules?</td><td>No. The user controls their browser.</td><td>Yes</td></tr></tbody></table><p>&quot;Full-stack&quot; just means an app with both.</p><h2 id="static-and-dynamic-sites" tabindex="-1">Static and dynamic sites <a class="header-anchor" href="#static-and-dynamic-sites" aria-label="Permalink to &quot;Static and dynamic sites&quot;">​</a></h2><ul><li>A <strong>static site</strong> is only files (HTML, CSS, JavaScript, images) that the host sends exactly as they are. There&#39;s no server code of your own. GitHub Pages hosts static sites, and weeks 1–8 use them. A static site can still be interactive: JavaScript runs in the browser, and localStorage remembers data on that one device.</li><li>A <strong>dynamic site</strong> also runs code on a server for each request. It can keep secrets, call APIs with a hidden key, and read or write a shared database. From week 9 you build these, and from week 10 you host them on Vercel, where each file in <code>api/</code> becomes a <a href="./glossary.html#serverless-function">serverless function</a>.</li></ul><p>You need a server when you have <strong>a secret to keep</strong> or <strong>data to share between users</strong>. Otherwise, static is simpler, free and faster.</p><h2 id="cdns-code-from-someone-elses-server" tabindex="-1">CDNs: code from someone else&#39;s server <a class="header-anchor" href="#cdns-code-from-someone-elses-server" aria-label="Permalink to &quot;CDNs: code from someone else&#39;s server&quot;">​</a></h2><p>A <strong>CDN</strong> (content delivery network) is a group of servers around the world that hand out copies of the same files, so each visitor downloads them from somewhere nearby. GitHub Pages and Vercel serve your own sites through CDNs, which is one reason a change can take a minute to show up everywhere.</p><p>Public CDNs such as jsDelivr also host copies of popular code libraries. A page can then load a library from its address, without installing anything. In week 13, your capstone&#39;s <code>public/lib/db.js</code> loads the Supabase library this way, from this address:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2.118.0/+esm</span></span></code></pre></div><p>Code loaded from a CDN runs inside your page with the same power as your own code, in every visitor&#39;s browser. So treat it like installing a package (<a href="./../setup/safety-contract.html">safety contract rule 6</a>): load only well-known libraries your plan names, from a well-known CDN, with a <strong>version in the address</strong>. <code>@2</code> means &quot;the newest 2.x release&quot;, so a big breaking change can&#39;t arrive unannounced; writing the full version number you tested is stricter still, because then your visitors get exactly the code you tested.</p><h2 id="databases" tabindex="-1">Databases <a class="header-anchor" href="#databases" aria-label="Permalink to &quot;Databases&quot;">​</a></h2><p>A <strong>database</strong> stores data on a server so that many people, on many devices, see the same thing. <em>Picture a shared spreadsheet: a <strong>table</strong> per kind of thing (notes, scores), a <strong>row</strong> per item, a <strong>column</strong> per detail.</em></p><p>Compare the two places your projects store data:</p><table tabindex="0"><thead><tr><th></th><th>localStorage (weeks 3–8)</th><th>Database (weeks 13–16)</th></tr></thead><tbody><tr><td>Where it lives</td><td>In one browser, on one device</td><td>On a server</td></tr><tr><td>Who sees it</td><td>Whoever uses that browser</td><td>Everyone the rules allow</td></tr><tr><td>Survives clearing the browser?</td><td>No</td><td>Yes</td></tr><tr><td>Needs access rules?</td><td>No, it&#39;s single-user</td><td><strong>Yes, always</strong></td></tr></tbody></table><p>Once data is shared, you have to decide who may read and change each row. In Supabase, the database enforces that with <a href="./glossary.html#row-level-security-rls">row-level security</a>. Without it, a public key plus a missing rule means anyone can read and change everything. That is exactly what happened to the apps in the <a href="./case-studies.html">Lovable and Moltbook case studies</a>, and to the 16,326 databases in the <a href="./case-studies.html#12-upguard-16326-exposed-supabase-databases">UpGuard case</a>.</p><h2 id="the-trust-boundary" tabindex="-1">The trust boundary <a class="header-anchor" href="#the-trust-boundary" aria-label="Permalink to &quot;The trust boundary&quot;">​</a></h2><p>A week 9–16 app has parts that run in different places. The <strong>trust boundary</strong> is the line between what the public can see and what only you and your host can see. Here is what sits on each side, and what crosses the line.</p><p><strong>Public side: assume anyone can see all of this.</strong></p><ul><li><strong>The visitor&#39;s browser:</strong> your HTML, CSS and JavaScript; localStorage on that device; every request and response (DevTools → Network); the Supabase project URL and publishable key (in <code>public/config.js</code>).</li><li><strong>Your GitHub repository (public):</strong> every file, and every old commit, forever.</li></ul><p><strong>Private side: only you and your host can see inside.</strong></p><ul><li><strong>Your server:</strong> <code>api/ask.js</code>, running on Vercel. It holds the environment variables (<code>LLM_API_KEY</code>, and the Supabase secret key if you use one), checks every input and sets limits.</li><li><strong>The database (Supabase):</strong> its row-level security policies decide, row by row, what each request may read or change.</li><li><strong>The LLM provider</strong> (Gemini, Groq and others): it receives requests only from your server.</li></ul><p><strong>What crosses the line:</strong></p><ol><li><strong>Browser → your server:</strong> <code>fetch(&quot;/api/ask&quot;)</code> with the user&#39;s question. No key.</li><li><strong>Your server → the LLM provider:</strong> the question, plus the API key in a request header. This happens entirely on the private side.</li><li><strong>Browser → the database:</strong> requests that carry the publishable key, straight from the page. The database&#39;s policies, not your page, decide what each one may do.</li></ol><p>Four rules follow:</p><ol><li><strong>Everything on the public side is public.</strong> That includes your front-end code, anything in localStorage, every network request, and every commit in a public repo, including old ones. &quot;Hidden&quot; in a variable or a minified file still means public.</li><li><strong>Secrets live only on the private side</strong>, in environment variables on the server. The Supabase secret key and your LLM API key never cross the line.</li><li><strong>Anything that crosses the line can be faked.</strong> A visitor can edit your JavaScript, skip your checks and send any request they like. So the server and the database must check every request themselves. That is where <a href="./glossary.html#authorization">authorization</a> lives.</li><li><strong>The publishable key is meant to cross the line</strong>, which is exactly why row-level security must be on for every table.</li></ol><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>One of the <a href="./without-ai-skills.html">six skills you must show without AI</a> is saying where authorization is enforced in your app. The answer is always a place on the private side: your server or your database&#39;s policies.</p></div><h2 id="a-short-devtools-tour" tabindex="-1">A short DevTools tour <a class="header-anchor" href="#a-short-devtools-tour" aria-label="Permalink to &quot;A short DevTools tour&quot;">​</a></h2><p>Every desktop browser has developer tools built in. They let you see what your page is really doing instead of guessing.</p><p><strong>Open them:</strong> press <strong>F12</strong>, or <strong>Ctrl+Shift+I</strong> (Windows, Linux, ChromeOS) or <strong>Cmd+Option+I</strong> (Mac). You can also right-click anything on a page and choose <strong>Inspect</strong>. These steps use Chrome or Edge. Firefox is almost the same, but calls the storage tab <strong>Storage</strong>. In Safari, first turn on Settings → Advanced → &quot;Show features for web developers&quot;.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Menus move. If you can&#39;t find a tab, look for a <code>»</code> or <code>+</code> button in the DevTools tab bar, or ask your assistant where it is in your browser.</p></div><table tabindex="0"><thead><tr><th>Tab</th><th>What it shows</th><th>Use it when</th></tr></thead><tbody><tr><td><strong>Elements</strong></td><td>The live page structure (the DOM) and the CSS applied to each part. You can edit both, and the changes vanish on reload.</td><td>&quot;Why is this button in the wrong place?&quot; Try a CSS change here before asking the AI.</td></tr><tr><td><strong>Console</strong></td><td>Errors in red, with the file and line number on the right. You can also type JavaScript here.</td><td>Your page is blank or a button does nothing. <strong>Always look here first.</strong></td></tr><tr><td><strong>Network</strong></td><td>Every request the page made: status code, size, time. Click one to see its headers, what was sent (Payload) and what came back (Response).</td><td>An API call fails, or you want to prove your key is not sent from the browser.</td></tr><tr><td><strong>Sources</strong></td><td>The actual files the browser downloaded.</td><td>Proving to yourself that front-end code is public. (Advanced: click a line number to pause the code there.)</td></tr><tr><td><strong>Application → Local Storage</strong></td><td>Everything your site saved in localStorage, as key–value pairs. You can edit or delete entries.</td><td>Checking what your app saved, or resetting it to test the empty state.</td></tr></tbody></table><p>Two more buttons worth knowing:</p><ul><li><strong>Device toolbar</strong> (the phone-and-tablet icon, or <strong>Ctrl+Shift+M</strong> / <strong>Cmd+Shift+M</strong> while DevTools is open) shows your page at phone size. Use it for your &quot;small screen&quot; <a href="./glossary.html#edge-case">edge case</a>.</li><li><strong>Disable cache</strong> (a checkbox in the Network tab) makes the browser fetch fresh files while DevTools is open. Handy when your changes don&#39;t show up.</li></ul><h2 id="try-it-10-minutes" tabindex="-1">Try it (10 minutes) <a class="header-anchor" href="#try-it-10-minutes" aria-label="Permalink to &quot;Try it (10 minutes)&quot;">​</a></h2><p>Open your own home page (or any page of yours) and open DevTools.</p><ol><li><strong>Elements:</strong> click the arrow icon at the top left of DevTools, then click your main heading. Double-click its text in the Elements panel and change it. The page changes. Reload: it&#39;s back. <em>You edited the DOM, not the file.</em></li><li><strong>Console:</strong> type <code>document.title</code> and press Enter. You get your page&#39;s title. Now type <code>document.querySelector(&#39;#does-not-exist&#39;).textContent = &#39;hi&#39;</code> and press Enter. Read the red error: <code>Cannot set properties of null</code>. It means &quot;the thing you asked for doesn&#39;t exist&quot;. You will see this error again.</li><li><strong>Network:</strong> reload the page. Find <code>index.html</code> (status <code>200</code>). Now visit a page on your site that doesn&#39;t exist, such as <code>/nope.html</code>, and find the <code>404</code>.</li><li><strong>Application → Local Storage:</strong> in the Console, type <code>localStorage.setItem(&#39;hello&#39;, &#39;world&#39;)</code>. Open Application → Local Storage → your site. There it is. Right-click it and delete it.</li><li><strong>Sources:</strong> open your site&#39;s files. Everything you wrote is there, readable by anyone. Keep that picture in mind in week 9.</li></ol><p>✅ <strong>Checkpoint:</strong> you can find a red error and its line number, find a request and its status code, and find what your site saved in localStorage.</p><h2 id="where-this-shows-up-in-the-course" tabindex="-1">Where this shows up in the course <a class="header-anchor" href="#where-this-shows-up-in-the-course" aria-label="Permalink to &quot;Where this shows up in the course&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Week</th><th>What you&#39;ll use from this page</th></tr></thead><tbody><tr><td><a href="./../weeks/01-hello-vibe-coding/">1</a> and <a href="./../weeks/02-ship-your-page/">2</a></td><td>HTML, CSS and JavaScript roles; URLs; static sites on GitHub Pages</td></tr><tr><td><a href="./../weeks/07-read-and-debug/">7</a></td><td>localStorage (your game and Project 1 use it from weeks 3–8), the DOM, DevTools Console and Application, status codes</td></tr><tr><td><a href="./../weeks/09-apis-and-secrets/">9</a> and <a href="./../weeks/10-servers-and-deployment/">10</a></td><td>HTTP, JSON, APIs, front end and back end, the trust boundary</td></tr><tr><td><a href="./../weeks/13-data-and-access/">13</a></td><td>Databases, authorization, row-level security, the publishable key</td></tr></tbody></table><p>Words you don&#39;t know are in the <a href="./glossary.html">glossary</a>.</p>`,83)])])}const g=t(r,[["render",n]]);export{p as __pageData,g as default};
